def transform_demo(input_grid):
    """Transform diamond centers to outputs"""
    H, W = len(input_grid), len(input_grid[0])
    output = [[0 for _ in range(W)] for _ in range(H)]

    # Find centers
    centers = []
    for r in range(H):
        for c in range(W):
            val = input_grid[r][c]
            if val not in [0, 3]:
                markers = sum(
                    input_grid[r + dr][c + dc] == 3
                    for dr, dc in [(-2, 0), (2, 0), (0, -2), (0, 2)]
                    if 0 <= r + dr < H and 0 <= c + dc < W
                )
                if markers == 4:
                    centers.append((r, c, val))

    for r, c, val in centers:
        dist = 2
        for r0 in [r - dist, r + dist]:
            for c0 in [c - dist, c + dist]:
                if 0 <= r0 < H and 0 <= c0 < W:
                    output[r0][c0] = 3 if val != 0 else 0
        for dr in range(-dist, dist + 1):
            for dc in range(-dist, dist):
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W:
                    output[nr][nc] = val if val != 0 else output[nr][nc]

    return output

